struct Session { conn: Connection, log: File }   // fields owned => dropped with self

impl Drop for Session {
    fn drop(&mut self) {                         // deterministic, at most once
        self.conn.shutdown();                    // fields drop after this
    }
}

fn handle(s: Session) -> std::io::Result<()> {
    s.round_trip()   // on return/?/panic, s and its log/conn are dropped here
}
